<script setup lang="ts">
import {ref,watch,computed,onUnmounted} from 'vue'
import {NModal,NSteps,NStep,NInput,NCheckboxGroup,NCheckbox,NRadioGroup,NRadio,NFormItem,NButton,NSpace,NAlert,useMessage} from 'naive-ui'
import {api,state} from '../store'
import {protocolNames} from '../domain'
const props=defineProps<{show:boolean}>(),emit=defineEmits(['update:show']),message=useMessage(),info=ref<any>(null),step=ref(1),busy=ref(false),result=ref(''),error=ref(false),url=ref('')
const form=ref({mode:'ip',domain:'',password:'',sni:'www.apple.com',protocols:['reality','hysteria2','tuic'],text:''});let timer:ReturnType<typeof setTimeout>|undefined,closed=false
const readonly=computed(()=>info.value&&!info.value.required)
watch(()=>props.show,async v=>{closed=!v;clearTimeout(timer);if(!v){form.value.password='';form.value.text='';return}try{info.value=await api('/api/setup');if(closed)return;step.value=1;result.value='';url.value='';busy.value=!!info.value.job.running;form.value={mode:info.value.mode||(info.value.domain?'domain':'ip'),domain:info.value.domain||'',password:'',sni:info.value.sni||'www.apple.com',protocols:info.value.required?(info.value.domain?['reality','hysteria2','tuic']:['reality']):info.value.protocols,text:''};if(busy.value)void poll()}catch(e){message.error((e as Error).message);emit('update:show',false)}})
watch(()=>form.value.mode,mode=>{if(readonly.value)return;if(mode==='ip'){form.value.protocols=form.value.protocols.filter(p=>['reality','shadowsocks'].includes(p));if(!form.value.protocols.length)form.value.protocols=['reality']}})
async function next(){if(readonly.value){step.value++;return}busy.value=true;try{if(step.value===1||step.value===3)await api('/api/setup/validate',form.value);if(step.value===2&&!form.value.protocols.length)throw Error('请选择至少一种协议');step.value++;result.value='';error.value=false}catch(e){result.value=(e as Error).message;error.value=true}finally{busy.value=false}}
async function apply(){busy.value=true;error.value=false;try{await api('/api/setup/apply',form.value);url.value=form.value.mode==='domain'?'https://'+form.value.domain.trim().replace(/\.+$/,'')+':'+info.value.panel_port+'/':'';result.value='正在初始化…';void poll()}catch(e){result.value=(e as Error).message;error.value=true;busy.value=false}}
async function poll(){if(closed)return;try{const v=await api('/api/setup');if(closed)return;result.value=v.job.message||'正在初始化…';if(v.job.running){timer=setTimeout(poll,1000);return}busy.value=false;if(v.job.ok){form.value.password='';form.value.text='';state.data={...state.data,setup_required:false};info.value=v;url.value=v.job.url;step.value=4}else{error.value=true;url.value=''}}catch{if(!closed){result.value='服务可能正在重启，请稍后通过新管理地址登录。';timer=setTimeout(poll,2500)}}}
function close(v:boolean){if(!v&&(busy.value||info.value?.required))return;emit('update:show',v)}
onUnmounted(()=>{closed=true;clearTimeout(timer);form.value.password='';form.value.text=''})
</script>
<template><NModal :show="show" @update:show="close" preset="card" title="初始化配置" class="dialog setup-dialog" :closable="!info?.required&&!busy" :mask-closable="!info?.required&&!busy" :close-on-esc="!info?.required&&!busy"><template v-if="info"><p class="muted">{{readonly?'当前服务器已完成初始化 · 只读查看':'完成新服务器的首次配置'}}</p><NSteps :current="step" size="small"><NStep title="管理与域名"/><NStep title="节点协议"/><NStep title="初始落地"/><NStep title="确认配置"/></NSteps><div class="setup-content"><template v-if="step===1"><div class="info-strip">服务器 IPv4 · {{info.server_ip}}</div><NFormItem label="入口模式"><NRadioGroup v-model:value="form.mode" :disabled="readonly"><NSpace><NRadio value="ip">IP 模式 · 无须域名</NRadio><NRadio value="domain">域名模式</NRadio></NSpace></NRadioGroup></NFormItem><NFormItem v-if="form.mode==='domain'" label="入口域名"><NInput v-model:value="form.domain" :disabled="readonly" placeholder="relay.example.com"/></NFormItem><p v-if="form.mode==='domain'" class="muted">A 记录指向本机，选择仅 DNS；申请证书需要公网 TCP 80 可达。</p><p v-if="form.mode==='ip'" class="info-strip">节点使用服务器 IP；管理面板继续通过 SSH 隧道访问，无须申请域名证书。</p><NFormItem label="管理员密码"><NInput v-model:value="form.password" type="password" :disabled="readonly" autocomplete="new-password" :placeholder="readonly?'已设置':'至少 14 位'"/></NFormItem></template><template v-else-if="step===2"><NCheckboxGroup v-model:value="form.protocols" :disabled="readonly"><div class="protocol-options"><NCheckbox v-for="p in ['reality','hysteria2','tuic','trojan','shadowsocks']" :key="p" :value="p" :disabled="form.mode==='ip'&&! ['reality','shadowsocks'].includes(p)" :label="protocolNames[p]"/></div></NCheckboxGroup><p v-if="form.mode==='ip'" class="muted">Trojan、Hysteria2 和 TUIC 在当前实现中需要域名与可信证书。</p><NFormItem v-if="form.protocols.includes('reality')" label="Reality 握手域名"><NInput v-model:value="form.sni" :disabled="readonly"/></NFormItem></template><template v-else-if="step===3"><p v-if="readonly">当前已配置 {{info.nodes}} 条落地，可在节点管理中维护。</p><template v-else><NFormItem label="初始 SOCKS5 落地（可选）"><NInput v-model:value="form.text" type="textarea" :autosize="{minRows:6,maxRows:10}" placeholder="地址|端口|账号|密码|名称&#10;每行一条，名称留空自动生成"/></NFormItem><p class="muted">可跳过此步，初始化后在节点管理中批量添加。</p></template></template><template v-else><dl><div><dt>入口地址</dt><dd>{{form.mode==='ip'?info.server_ip:form.domain}}</dd></div><div><dt>启用协议</dt><dd>{{form.protocols.map(p=>protocolNames[p]).join(' / ')}}</dd></div><div><dt>初始落地</dt><dd>{{readonly?info.nodes+' 条':form.text.trim()?'已填写，提交前自动校验':'稍后添加'}}</dd></div></dl><p v-if="result&&!url&&!error&&form.mode==='ip'" class="info-strip">请保持 SSH 隧道连接，刷新当前页面后使用新密码登录。</p><NButton v-if="url" tag="a" :href="url" target="_blank" rel="noopener" type="primary" secondary>打开 HTTPS 管理面板</NButton></template></div><NAlert v-if="result" :type="error?'error':'info'" :show-icon="false">{{result}}</NAlert></template><template #footer><NSpace justify="end"><NButton :disabled="step===1||busy" @click="step--">上一步</NButton><NButton v-if="step<4" type="primary" :loading="busy" @click="next">{{step===3&&!readonly&&!form.text.trim()?'跳过，稍后添加':'下一步'}}</NButton><NButton v-else-if="readonly" type="primary" @click="emit('update:show',false)">返回面板</NButton><NButton v-else type="primary" :loading="busy" @click="apply">完成初始化</NButton></NSpace></template></NModal></template>
